INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-001$m$, NULL, $m$0: Remote service off 1: CSS remote service on 2: @Remote service on CE Call Performs the CE Call at the start or end of the service.$m$, NULL, NULL, NULL, NULL, $m$[0 to 2 / 2 / 1 /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-002$m$, NULL, $m$0: Start of the service 1: End of the service Note: This SP is activated only when SP 5816-1 is set to "2". Function Flag Enables or disables the remote service function.$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 0 / 1 /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-003$m$, NULL, $m$0: Disabled, 1: Enabled Note: This SP setting is changed to "1" after @Remote registor has been completed.$m$, NULL, NULL, NULL, NULL, $m$[0 to 1 / 0 / 1 /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-004$m$, NULL, $m$Notification of a common certification without ID2.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-005$m$, NULL, $m$Notification that no certification was issued.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-006$m$, NULL, $m$Notification that GW URL does not exist.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-007$m$, NULL, $m$0: Uses the RCG certification 1: Does no use the RCG certification RCG Connect Timeout Program$m$, NULL, NULL, NULL, NULL, $m$[0 to 1 / 0 / 1 /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-008$m$, NULL, $m$Specifies the connect timeout interval when calling the RCG. RCG Write Timeout$m$, NULL, NULL, NULL, NULL, $m$[1 to 90 / 10 / 1 second /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-009$m$, NULL, $m$Specifies the write timeout interval when calling the RCG. RCG Read Timeout$m$, NULL, NULL, NULL, NULL, $m$[1 to 100 / 60 / 1 second /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-010$m$, NULL, $m$Specifies the read timeout interval when calling the RCG. Port 80 Enable$m$, NULL, NULL, NULL, NULL, $m$[1 to 100 / 60 / 1 second /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-011$m$, NULL, $m$Enables/disables access via port 80 to the SOAP method. 0: Disabled, 1: Enabled 12 @Remote Communication Permission Setting This SP code is designed to allow the operator to disable @Remote communication the printer function manually before copying confidential or sensitive documents. This prevents the contents of the copied documents from inadvertently being printed or leaked over the network to an outside destination. 0: Disabled. Machine is not temporarily disconnected from network. 1: Enabled. Machine is temporarily disconnected from network and the machine will not print while confidential or sensitive documents are being copied. 2: Control mode. Only some SP codes can be used to acquire or write data. RFU (Remote Frimware Update) Timing Selects the RFU timing.$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 0 / ± ] [0 to 2/1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-012$m$, NULL, $m$notified of the certification update request. The notification of the request for certification update has completed$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-013$m$, NULL, $m$successfully, and the system is waiting for the certification update request from the rescue GW URL. The notification of the certification request has been received from the rescue GW controller, and the certification is being stored. The certification has been stored, and the GW URL is being notified of the successful completion of this event. The storing of the certification has failed, and the GW URL is being notified of the failure of this event. The certification update request has been received from the GW URL, the GW URL was notified of the results of the update after it was completed, but a certification error has been received, and the rescue certification is being recorded. The rescue certification of No. 17 has been recorded, and the GW URL is being notified of the failure of the certification update. CERT: Error Displays a number code that describes the reason for the request for update of the certification.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-014$m$, NULL, $m$RCG Error Cause Displays the cause of an RCG error. Where Cumin is used, normally displays "0". 0:Normal condition 1:Error If "1" is displayed, this means that the authentication from client to server failed when the network re-booted. To restore normal operation, cycle the machine off/on to return a "0" (normal condition). RCG ± C Registed$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-021$m$, NULL, $m$This SP displays the Embedded RC Gate installation end flag. 0: Installation not completed 1: Installation completed RCG ± C Regist Detail This SP displays the Embedded RC Gate installation status. 22 0: RCG device not registered 1: RCG device registered 2: Device registered Connect Type (N/M) This SP displays and selects the Embedded RC Gate connection method.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-023$m$, NULL, $m$[0 or 1 / 0 / 1 /step 0: Internet connection 1: Dial-up connection Cert. Expire Timing DFU Proximity of the expiration of the certification. Use Proxy$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-062$m$, NULL, $m$This SP setting determines if the proxy server is used when the machine communicates with the service center. Proxy Host Program This SP sets the address of the proxy server used for communication between Mode Tables Embedded RC Gate-N and the gateway. Use this SP to set up or display the$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-063$m$, NULL, $m$customer proxy server address. The address is necessary to set up Embedded RC Gate-N. Note: The address display is limited to 128 characters. Characters beyond the 128 character are ignored. This address is customer information and is not printed in the SMC report. Proxy Port Number This SP sets the port number of the proxy server used for communication$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-064$m$, NULL, $m$between Embedded RC Gate-N and the gateway. This setting is necessary to set up Embedded RC Gate-N. Note: This port number is customer information and is not printed in the SMC report. Proxy User Name This SP sets the HTTP proxy certification user name.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-065$m$, NULL, $m$Note: The length of the name is limited to 31 characters. Any character beyond the 31st character is ignored. This name is customer information and is not printed in the SMC report. Proxy Password This SP sets the HTTP proxy certification password.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-066$m$, NULL, $m$Note: The length of the password is limited to 31 characters. Any character beyond the 31st character is ignored. This name is customer information and is not printed in the SMC report. CERT: Up State Displays the status of the certification update.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-067$m$, NULL, $m$The rescue certification setting is completed and the GW URL is being$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-069$m$, NULL, $m$CERT: Up ID The ID of the request for certification.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-083$m$, NULL, $m$Firmware Up Status Displays the status of the firmware update.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-085$m$, NULL, $m$Firm Up User Check This SP setting determines if the operator can confirm the previous version of the firmware before the firmware update execution. If the option to confirm the previous version is selected, a notification is sent to the system manager and the firmware update is done with the firmware files from the URL.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-086$m$, NULL, $m$Firmware Size Allows the service technician to confirm the size of the firmware data files during the firmware update execution.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-087$m$, NULL, $m$CERT: Macro Ver. Displays the macro version of the @Remote certification.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-088$m$, NULL, $m$CERT: PAC Ver. Displays the PAC version of the @Remote certification.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-089$m$, NULL, $m$CERT: ID2 Code Displays ID2 for the @Remote certification. Spaces are displayed as underscores (_). Asteriskes (*) indicate that no @Remote certification exists. "000000___________" indicates "Common certification".$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-090$m$, NULL, $m$CERT: Subject Displays the common name of the @Remote certification subject. CN = the following 17 bytes. Spaces are displayed as underscores (_). Asterisks (*) indicate that no @Remote certification exists. "000000___________" indicates "Common certification".$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-091$m$, NULL, $m$CERT: Serial No. Displays serial number for the @Remote certification. Asterisks (*) indicate that no @Remote certification exists.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-092$m$, NULL, $m$CERT: Issuer Displays the common name of the issuer of the @Remote certification. CN = the following 30 bytes. Asteriskes () indicate that no @Remote certification exists.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-093$m$, NULL, $m$CERT: Valid Start Displays the start time of the period for which the current @Remote certification is enabled.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-094$m$, NULL, $m$CERT: Valid End Displays the end time of the period for which the current @Remote certification is enabled.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-095$m$, NULL, $m$Server ON Check Program Determines how the Server On Check is conducted. Mode Tables 0: Precision check 1: Mitigation check Note: "0" is used for GW/NRS connection ands "1" is used for GW/Emulator connection.$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-096$m$, NULL, $m$GW Host DFU A debug tool.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-097$m$, NULL, $m$GW URL Path DFU A debug tool.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-810-099$m$, NULL, $m$Debug Rescue/WURL Set DFU A debug tool. 102 CERT: Encrypt Level Displays the strength of encryption used for NRS authentication. The displayed value is not the value acquired from the authentication domain, rather it is the value stored in NVRAM when authentication is written. When NRS starts up, if there is a mismatch between this SP setting and the authentication encryption, then the SP value is updated. Selection Country Not used Line Type Automatic Judgment Not used Line Type Judgment Result Not used Selection Dial/Push Not used Outside Line/Outgoing Number Not used Dial Up User Name Not used Dial Up Password Not used Local Phone Number Not used Connection Timing Adjustment: Incoming Not used Access Point Not used Line Connecting Not used Modem Serial Number Not used Retransmission Limit Not used 186 RCG-CM Debug Bit SW DFU A debug tool. FAX TX Priorit Not used 200 Manual Polling Not used Regist: Status Program Displays a number that indicates the status of the @Remote service device. Mode Tables 0: Neither the @Remote device nor Embedded RCG Gate is set. 1: The Embedded RCG Gate is being set. Only Box registration is completed. 201 In this status, @Remote device cannot communicate with this device. 2: The Embedded RCG Gate is set. In this status, the @Remote device cannot communicate with this device. 3: The @Remote device is being set. In this status the Embedded RCG Gate cannot be set. 4: The @Remote module has not started. 202 Letter Number Allows entry of the request number needed for the Embedded RCG Gate. 203 Confirm Execute Executes the confirmation request to the @Remote Gateway. 204 Confirm Result Displays a number that indicates the result of the confirmation executed with SP5816-203. 0: Succeeded 1: Confirmation number error 2: Registration in progress 3: Proxy error (proxy enabled) 4: Proxy error (proxy disabled) 5: Proxy error (Illegal user name or password) 6: Communication error 7: Certification update error 8: Other error 9: Confirmation executing Confirm Place 205 Displays the result of the notification sent to the device from the Gateway in answer to the confirmation request. Displayed only when the result is registered at the Gateway. 206 Register Execute Executes "Embedded RCG Registration". Register Result Displays a number that indicates the registration result. 0: Succeeded 2: Registration in progress 3: Proxy error (proxy enabled) 207 4: Proxy error (proxy disabled) 5: Proxy error (Illegal user name or password) 6: Communication error 7: Certification update error 8: Other error 9: Registration executing Error Code 208 Displays a number that describes the error code that was issued when either SP5816-204 or SP5816-207 was executed. Cause Code Meaning Illegal Modem -11001 Chat parameter error Parameter -11002 Chat execution error -11003 Unexpected error -12002 Inquiry, registration attempted without acquiring device status. Operation Error, -12003 Attempted registration without execution Incorrect Setting of an inquiry and no previous registration. -12004 Attempted setting with illegal entries for certification and ID2. @Remote communication is prohibited. - -12005 The device has an Embedded RC gate-related problem. -12006 A confirmation request was made after the confirmation had been already completed. -12007 The request number used at registration was different from the one used at confirmation. -12008 Update certification failed because mainframe was in use. -2385 Attempted dial up overseas without the correct international prefix for the Service telephone number. Program Error Caused by -2387 Not supported at the Service Center Mode Tables Response from GW -2389 Database out of service URL -2390 Program out of service -2391 Two registrations for same device -2392 Parameter error -2393 RCG device not managed -2394 Device not managed -2395 Box ID for RCG device is illegal - -2396 Device ID for RCG device is illegal -2397 Incorrect ID2 format -2398 Incorrect request number format 209 Instl Clear Releases the setting on a machine that has been set for use with Cumin. 250 CommLog Print Prints the communication log.$m$, NULL, NULL, NULL, NULL, $m$[1 to 2/1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-821-002$m$, NULL, $m$RCG IP Address Sets the IP address of the RCG (Remote Communication Gate) destination for call processing at the remote service center.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-821-003$m$, NULL, $m$RCG Port Number Sets the RCG port number of the destination for processing calls to the @Remote service center.$m$, NULL, NULL, NULL, NULL, $m$[0 to 65 535/443/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-821-004$m$, NULL, $m$RCG URL Path Sets the URL path of the destination for processing calls to the @Remote service center.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-821-017$m$, NULL, $m$Numeric characters allowed (0 to 17)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-824$m$, NULL, $m$NVRAM Data Upload$m$, NULL, NULL, NULL, $m$Uploads the UP and SP mode data (except for counters and the serial number) from NVRAM on the control board to an SD card. Note: While using this SP mode, always keep the front cover open. This prevents a software module accessing the NVRAM during the upload.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-825$m$, NULL, $m$NVRAM Data Download$m$, NULL, NULL, NULL, $m$Downloads data from an SD card to the NVRAM in the machine. After downloading is completed, remove the SD card and turn the machine power off and on.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-001$m$, NULL, $m$IPv4 Address (Ethernet/IEEE 802.11) Allows you to confirm and reset the IPv4 address for Ethernet and wireless LAN (802.11): aaa.bbb.ccc.ddd$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-002$m$, NULL, $m$Subnet Mask (Ethernet/IEEE 802.11) Allows you to confirm and reset the IPv4 subnet mask for Ethernet and wireless LAN (802.11): aaa.bbb.ccc.ddd$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-003$m$, NULL, $m$Default Gatewary (Ethernet/IEEE 802.11) Allows you to confirm and reset the IPv4 default gateway used by the network Program for Ethernet and wireless LAN (802.11): aaa.bbb.ccc.ddd$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-006$m$, NULL, $m$DHCP (Ethernet/IEEE 802.11) Allows you confirm and change the setting that determines whether the IP address is used with DHCP on an Ethernet or wireless (802.11) LAN network. 0: Not used (manual setting) 1: Used$m$, NULL, NULL, NULL, NULL, $m$[0 to 1 / 1 / 1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-016$m$, NULL, $m$bits each. 161 IPv6 Stateless Auto Setting Enables or disables the automatic setting for IPv6 stateless. 0: Disable, 1: Enable 236 Web Item Visible Displays or does not display the Web system items. 0: Not displayed, 1: Displayed bit0: Net RICOH bit1: Consumable Supplier bit2-15: Reserved (all) 237 Web shopping Link Visible Displays or does not display the link to Net RICOH on the top page and link page of the web system. 0: Not display, 1:Display 238 Web Supplies Link visible Displays or does not display the link to Consumable Supplier on the top page and link page of the web system. 0: Not display, 1:Display 239 Web Link 1 Name This SP confirms or changes the URL1 name on the link page of the web system. The maximum characters for the URL name are 31 characters. 240 Web Link 1 URL This SP confirms or changes the link to URL1 on the link page of the web system. The maximum characters for the URL are 127 characters. 241 Web Link 1 visible Displays or does not display the link to URL1 on the top page of the web system. 0: Not display, 1:Display 242 Web Link 2 Name Same as "-239" 243 Web Link 2 URL Same as "-240" 244 Web Link 2 visible Same as "-241" 249 DHCPv6 DUID$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 1 / 1 /step] [0 x 0000 to 0 x ffff / 0 x ffff] [0 to 1 / 1 / 1] [0 to 1 / 1 / 1] [0 to 1 / 1 / 1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-021$m$, NULL, $m$Active IPv4 Address Allows you to confirm the IPv4 address that was used when the machine started up with DHCP.$m$, NULL, NULL, NULL, NULL, NULL);
INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-022$m$, NULL, $m$Active IPv4 Subnet Mask Allows you to confirm the IPv4 subnet mask setting that was used when the machine started up with DHCP.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-023$m$, NULL, $m$Active IPv4 Gateway Address Allows you to confirm the IPv4 default gateway setting that was used when the machine started up with DHCP. 50 1284 Compatibility (Centro) Enables or disables 1284 Compatibility. 0: Disabled, 1: Enabled$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 1 / 1 / step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-052$m$, NULL, $m$ECP (Centro) Enables or disables ECP Compatibility. 0: Disabled, 1: Enabled Note: This SP is activated only when SP5-828-50 is set to "1".$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 1 / 1 / step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-065$m$, NULL, $m$Job Spooling Enables/disables Job Spooling. 0: Disabled, 1: Enabled$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 0 / 1 / step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-066$m$, NULL, $m$Job Spooling Clear: Start Time Treatment of the job when a spooled job exists at power on. 0: ON (Data is cleared) 1: OFF (Automatically printed)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-069$m$, NULL, $m$Job Spooling (Protocol) Validates or invalidates the job spooling function for each protocol. 0: Validates 1: Invalidates bit0: LPR bit1: FTP bit2: IPP bit3: SMB bit4: BMLinkS bit5: DIPRINT bit6: sftp bit7: (Reserved) 87 @Remote Protocol Cnt$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-090$m$, NULL, $m$TELNET (0: OFF 1: ON) Enables or disables the Telnet protocol. 0: Disable, 1: Enable$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 1 / ± ]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-828-091$m$, NULL, $m$Web (0: OFF 1: ON) Program Enables or disables the Web operation. Mode Tables 0: Disable, 1: Enable 145 Active IPv6 Link Local Address This is the IPv6 local address link referenced on the Ethernet or wireless LAN in the format: "Link Local Address" + "Prefix Length" The IPv6 address consists of a total 128 bits configured in 8 blocks of 16 bits each. 147 Active IPv6 Stateless Address 1 149 Active IPv6 Stateless Address 2 151 Active IPv6 Stateless Address 3 153 Active IPv6 Stateless Address 4 155 Active IPv6 Stateless Address 5 SP codes 147 to 155 are the IPv6 status addresses (1 to 5) referenced on the Ethernet or wireless LAN in the format: "Status Address" + "Prefix Length" The IPv6 address consists of a total 128 bits configured in 8 blocks of 16 bits each. 156 IPv6 Manual Address This SP is the IPv6 manually set address referenced on the Ethernet or wireless LAN in the format: "Manual Set Address" + "Prefix Length" The IPv6 address consists of a total 128 bits configured in 8 blocks of 16 bits each. 158 IPv6 Gateway Address This SP is the IPv6 gateway address referenced on the Ethernet or wireless LAN. The IPv6 address consists of a total 128 bits configured in 8 blocks of$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 1 / ± ]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-831$m$, NULL, $m$Initial Setting Mode Clear$m$, NULL, NULL, NULL, $m$Press [EXECUTE] to restore the inisial settings of all SP codes to their initial Appendix: (factory) settings. Service Note: This SP does not reset time settings or user tool settings. Program HDD Mode Tables$m$, $m$[EXECUTE]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-832-001$m$, NULL, $m$HDD Formatting (All)$m$, NULL, NULL, NULL, $m$execution ends, cycle the machine power off and on.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-832-002$m$, NULL, $m$HDD Formatting (IMH)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-832-003$m$, NULL, $m$HDD Formatting (Thumbnail)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-832-004$m$, NULL, $m$HDD Formatting (Job Log)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-832-005$m$, NULL, $m$HDD Formatting (Printer Fonts)$m$, NULL, NULL, NULL, NULL, NULL),
