  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-846-094$m$, NULL, $m$Shows the status of the encryption function for the address book data. Resolution Reduction 5847 5847-002 through 5847-006 changes the default settings of image data sent externally by the Net File page reference function. 5847 21 sets the default for JPEG image quality of image files controlled by NetFile. "Repository" refers to jobs to be printed from the document server with a PC and the DeskTopBinder software.$m$, NULL, NULL, NULL, NULL, $m$[0 to 2/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-846-099$m$, NULL, $m$Repository: Download Image Setting 100 Repository: Download Image Max. Size 210 Setting: Log Type: Job 1 Switches access control on/off. 0000: OFF, 0001: ON 211 Setting: Log Type: Job 2 Switches access control on/off. 0000: OFF, 0001: ON 212 Setting: LogType Access Switches access control on/off. 0000: OFF, 0001: ON 213 Setting: Primary Srv DFU 214 Setting: Secondary Srv Specifies the maximum size of the image data that the machine can download. 215 Setting: Start Time 216 Setting: Interval Time 217 Setting: Timing$m$, NULL, NULL, NULL, NULL, $m$[1 to 1024/1 K] [1 to 1024 / 1024 / 1 MB /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-849-001$m$, NULL, $m$Display The "Counter Clear Day" has been changed to "Installation Date" or "Inst. Date".$m$, NULL, NULL, NULL, $m$Displays or prints the installation date of the machine.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-849-002$m$, NULL, $m$Switch to Print Determines whether the installation date is printed on the printout for the total counter. Service Program 0: No Print, 1: Print$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/1]$m$),
