  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-851$m$, NULL, $m$Bluetooth Mode$m$, NULL, NULL, NULL, $m$Sets the operation mode for the Bluetooth unit. Press either key. [0: Public] [1: Private]$m$, $m$[0: Public] [1: Private]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-853$m$, NULL, $m$Stamp Data Download$m$, NULL, NULL, NULL, $m$Push [Execute] to download the fixed stamp data from the machine ROM onto the hard disk. Then these stamps can be used by the system. If this is not done, the user will not have access to the fixed stamps ("Confidential", "Secret", etc.). You must always execute this SP after replacing the HDD or after formatting the HDD. Always switch the machine off and on after executing this SP.$m$, $m$[Execute]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-856$m$, NULL, $m$Remote ROM Update$m$, NULL, NULL, NULL, $m$When set to "1" allows reception of firmware data via the local port (IEEE 1284) during a remote ROM update. This setting is reset to zero after the machine is cycled off and on. Allows the technician to upgrade the firmware using a parallel cable. [0 to 1/1] 0: Not allowed, 1: Allowed$m$, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-001$m$, NULL, $m$Switches the debug log feature on and off. The debug log cannot be captured until this feature is switched on. 0: OFF, 1: ON Target (2: HDD 3: SD) Selects the storage device to save debug logs information when the$m$, NULL, NULL, NULL, $m$On/Off (1:ON 0:OFF)$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-002$m$, NULL, $m$conditions set with SP5-858 are satisfied. 2: HDD, 3: SD Card Save to HDD Saves the debug log of the input SC number in memory to the HDD.$m$, NULL, NULL, NULL, NULL, $m$[ 2 to 3 / 2 / 1 /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-005$m$, NULL, $m$A unique file name is generated to avoid overwriting existing file names on the SD Card. Up to 4MB can be copied to an SD Card. 4 MB segments can be copied one by one to each SD Card. Save to SD Card Saves the debug log of the input SC number in memory to the SD card.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-009$m$, NULL, $m$Copy HDD to SD Card (Latest 4 MB)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-010$m$, NULL, $m$Copy HDD to SD Card (Latest 4 MB Any Key)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-011$m$, NULL, $m$Erase HDD Debug Data$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-012$m$, NULL, $m$Erase SD Card Debug Data$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-013$m$, NULL, $m$Free Space on SD Card$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-014$m$, NULL, $m$Copy SD to SD (Latest 4 MB)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-015$m$, NULL, $m$Copy SD to SD (Latest 4 MB Any Key)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-016$m$, NULL, $m$Make HDD Debug$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-857-017$m$, NULL, $m$Make SD Debug Debug Save When$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-858-001$m$, NULL, $m$Engine SC Error (0:OFF 1:ON) Program Stores SC codes generated by copier engine errors.$m$, NULL, NULL, NULL, $m$destination selected by SP5857-002. SP5858-003 stores one SC specified by number.$m$, NULL);
