  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-858-002$m$, NULL, $m$Controller SC Error (0:OFF 1:ON) Stores SC codes generated by GW controller errors.$m$, NULL, NULL, NULL, NULL, NULL),
