  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-859-008$m$, NULL, $m$Key 8$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-859-009$m$, NULL, $m$Key 9$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-859-010$m$, NULL, $m$Key 10$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-860-020$m$, NULL, $m$Sets the amount of time to wait before saving a mail that breaks up during reception. The received mail is discarded if the remaining portion of the mail is not received during this prescribed time. MDN Response RFC2298Compliance$m$, NULL, NULL, NULL, $m$Partial Mail Receive Timeout [1 to 168/72/1]$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-860-021$m$, NULL, $m$Determines whether RFC2298compliance is switched on for MDN reply mail. 0: No, 1: Yes SMTP Auth. From Field Replacement Determines whether the FROM item of the mail header is switched to the$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-860-022$m$, NULL, $m$validated account after the SMTP server is validated. 0: No. "From" item not switched. 1: Yes. "From" item switched. SMTP Auth Direct Sending Occasionally, all SMTP certifications may fail with SP5860 006 set to "2" to enable encryption during SMTP certification for the SMTP server. This can occur if the SMTP server does not meet RFC standards. In such cases you can use this SP to set the SMTP certification method directly. However, this$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-860-025$m$, NULL, $m$SP can be used only after SP5860 003 has been set to "1" (On). Bit0: LOGIN Bit1: PLAIN Bit2: CRAM_MD5 Bit3: DIGEST_MD5 Bit4 to Bit 7: Not Used S/MIME: MIME Header Settings Selects the MIME header type of an e-mail sent by S/MIME. Program$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-860-026$m$, NULL, $m$0: Microsoft Outlook Express standard 1: Internet Draft standard 2: RFC standard S/MIME: Authentication Check$m$, NULL, NULL, NULL, NULL, $m$[0 to 2 / 0 / 1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-860-028$m$, NULL, $m$Determines whether the destination is authenticated for sending S/MIME mail. 0: No Checking 1: Checking$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-866-001$m$, NULL, $m$Report Validity Enables or disables the e-mail notification to @Remote. 0: Enable, 1: Disable$m$, NULL, NULL, NULL, $m$This SP controls operation of the email notification function.$m$, $m$[0 or 1 / 0 / 1 ]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-866-005$m$, NULL, $m$Add Date Field Disables and re-enables the addition of a date field to the email notification.$m$, NULL, NULL, NULL, NULL, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-870-001$m$, NULL, $m$Writing$m$, NULL, NULL, NULL, $m$Writes to flash ROM the common proof for validating the device for NRS specifications.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-870-003$m$, NULL, $m$Initialize Initializes the set certification. When the GW controller board is replaced with a new one for repair, you must execute the "Initiralize (-003)" and "Writing (-001)" just after the new board replacement. NOTE: Turn off and on the main power switch after the "Initiralize (-003)" and "Writing (-001)" have been done.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-870-004$m$, NULL, $m$Common KeyInfo Writing (2048 bit) Wrties the authentication data used for @Remote into the flash ROM.$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-873-001$m$, NULL, $m$Move Exec Executes the move from one SD card to another.$m$, NULL, NULL, NULL, $m$Allows you to move applications from one SD card another.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-873-002$m$, NULL, $m$Undo Exec This is an undo function. It cancels the previous execution. SC Auto Reboot$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-875-001$m$, NULL, $m$Data Overwrite Security Enables the Data Overwrite Security unit. Touch on the operation panel. Then cycle the machine off/on.$m$, NULL, NULL, NULL, NULL, $m$[EXECUTE]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-875-002$m$, NULL, $m$HDD Encryption Enables the Copy Data Security unit. Touch on the operation panel. Then cycle the machine off/on.$m$, NULL, NULL, NULL, NULL, $m$[EXECUTE]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-875-011$m$, NULL, $m$Clear NCS Security Setting$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-875-015$m$, NULL, $m$Clear UCS Security Setting Option Setup 5878 This SP enables the DOS application (Data Overwrite Security). Do this SP after installing Data Overwrite Security Unit.)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-881$m$, NULL, $m$Fixed Phase Block Erasing$m$, NULL, NULL, NULL, $m$Touch [EXECUTE] on the operation panel. Then erase all the fixed phase block.$m$, $m$[EXECUTE]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-000$m$, NULL, $m$Forbid all document server access (1)$m$, NULL, NULL, NULL, NULL, NULL),
