  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-002$m$, NULL, $m$Forbid print function (1)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-003$m$, NULL, $m$Forbid fax TX (1)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-004$m$, NULL, $m$Forbid scan sending (1)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-005$m$, NULL, $m$Forbid downloading (1)$m$, NULL, NULL, NULL, NULL, NULL),
