  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-007$m$, NULL, $m$Reserved$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-020$m$, NULL, $m$Doc Svr Acc Ctrl Bit Meaning$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-050$m$, NULL, $m$Doc Svr Format$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-885-051$m$, NULL, $m$Doc Svr Trans Service 100 Set Signature Program 101 Set Encryption Determines whether the scanned documents with the WIM are encrypted when they are transmitted by an e-mail. 0: Not encrypted, 1: Encrypted 200 Detect Memory Leak 201 Doc Server Timeout SD Get Counter CTL This SP determines whether the ROM can be updated.$m$, NULL, NULL, NULL, NULL, $m$[0 or 1 / 0 / -]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-887$m$, NULL, $m$This SP sends a text file to an SD card inserted in SD card Slot 2 (lower slot).$m$, NULL, NULL, NULL, $m$The operation stores. The file is stored in a folder created in the root directory of the SD card called SD_COUNTER. The file is saved as a text file (*.txt) prefixed with the number of the machine. 1. Insert the SD card in SD card Slot 2 (lower slot). 2. Select SP5887 then touch [EXECUTE]. 3. Touch [Execute] in the message when you are prompted.$m$, $m$[EXECUTE] [Execute]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-888$m$, NULL, $m$Personal Information Protect$m$, NULL, NULL, NULL, $m$Selects the protection level for logs. [0 to 1 / 0 / 1} 0: No authentication, No protection for logs 1: No authentication, Protected logs (only an administrator can see the logs)$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-893-001$m$, NULL, $m$SDK-1$m$, NULL, NULL, NULL, $m$Displays the counter name of each SDK application.$m$, NULL),
