  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-893-003$m$, NULL, $m$SDK-3$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-893-004$m$, NULL, $m$SDK-4$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-893-005$m$, NULL, $m$SDK-5$m$, NULL, NULL, NULL, NULL, NULL),
