INSERT INTO manual_entries (manual_id, type, code, level, title, detection, causes, solution, description, setting) VALUES
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-894$m$, NULL, $m$External Charge Unit Setting Switch Charge Mode$m$, NULL, NULL, NULL, $m$[0 to 2/0/1]$m$, $m$[0 to 2/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-899$m$, NULL, $m$PM Double Count$m$, NULL, NULL, NULL, $m$This SP sets the PM counter to count double for paper longer than 420 mm. [0 to 1/0/1] 0: OFF 1: PM registers a double-count for paper longer than 420 mm in the sub scan direction.$m$, $m$[0 to 1/0/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-907$m$, NULL, $m$Plug & Play Maker/Model Name$m$, NULL, NULL, NULL, $m$Selects the brand name and the production name for Windows Plug & Play. This information is stored in the NVRAM. If the NVRAM is defective, these names should be registered again. After selecting, press the "Original Type" key and "#" key at the same time. When the setting is completed, the beeper sounds five times.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-913-001$m$, NULL, $m$Tray 1 Select a paper size for the tray 1. 0: A4, 1: 81/2x11$m$, NULL, NULL, NULL, $m$If no key is pressed when there is an application with display control rights, these SP settings allow the system to shift to the application standing by after the specified time as elapse. This SP switches the switchover permission timer on/off. [0 to 1/1/1] 0: OFF 1: ON Mechanical Counter Detection Appendix: Displays whether the mechanical counter is installed in the machine. Program [0 to 2] 0: Not detected Mode Tables 1: Detected 5915 2: Unknown 5952 Fact Adjust Mode 5959 Paper Size$m$, $m$[0 or 1 / NA: 1, Others: 0 / 1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-913-005$m$, NULL, $m$Tray 4 (LCT) Japan only$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-913-006$m$, NULL, $m$Cover Sheet$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-967$m$, NULL, $m$Copy Server: Set Function$m$, NULL, NULL, NULL, $m$Enables and disables the document server. This is a security measure that prevents image data from being left in the temporary area of the HDD. After changing this setting, you must switch the main switch off and on to enable the new setting. [0 to 1/1] 0: ON, 1: OFF$m$, $m$[0 to 1/1]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-974$m$, NULL, $m$Cherry Server$m$, NULL, NULL, NULL, $m$Selects which version of the Scan Router application program, "Light" or "Full (Professional)", is installed. [0 to 1 / 0 / 1 /step] 0: Light version (supplied with this machine) 1: Full version (optional) Device Setting$m$, $m$[0 to 1 / 0 / 1 /step]$m$),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-985-001$m$, NULL, $m$On Board NIC 0: Disable, 1: Enable$m$, NULL, NULL, NULL, $m$SP to enable and disable these features. In order to use the NIC and USB functions built into the controller board, these SP codes must be set to "1".$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-985-002$m$, NULL, $m$On Board USB SP Print Mode$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-990-001$m$, NULL, $m$All (Data List)$m$, NULL, NULL, NULL, $m$copy screen, select the paper size, then press Start. Select A4/LT (Sideways) or larger to ensure that all the information prints. Press SP Window to return to the SP mode, select the desired print, and press Execute.$m$, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-990-002$m$, NULL, $m$SP (Mode Data List)$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-990-003$m$, NULL, $m$User Program Data$m$, NULL, NULL, NULL, NULL, NULL),
  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-990-004$m$, NULL, $m$Logging Data Program$m$, NULL, NULL, NULL, NULL, NULL),
