  ('a1b2c3d4-0000-4000-8000-000000007502', $m$codigo$m$, $m$SP5-990-006$m$, NULL, $m$Non-Default (Prints only SPs set to values other than defaults.)$m$, NULL, NULL, NULL, NULL, NULL),
